CREATE OR REPLACE FUNCTION public.triar_documento(_id uuid,_tipo text,_situacao text,_obs text,_nota uuid DEFAULT NULL,_carga uuid DEFAULT NULL,_entrega uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p comprovantes; load_id uuid:=_carga; note_id uuid:=_nota; delivery_note uuid; nload uuid; BEGIN IF NOT private.can_write(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF _tipo NOT IN ('canhoto','devolucao','recibo','recusa','outro','nao_identificado') OR _situacao NOT IN ('pendente','analisado','nova_foto') THEN RAISE EXCEPTION 'Classificação inválida'; END IF; SELECT * INTO p FROM comprovantes WHERE id=_id FOR UPDATE; IF NOT FOUND OR p.status IN ('aprovado','rejeitado') THEN RAISE EXCEPTION 'Documento já finalizado ou inexistente'; END IF; IF _entrega IS NOT NULL THEN SELECT nota_id INTO delivery_note FROM entregas WHERE id=_entrega; IF NOT FOUND THEN RAISE EXCEPTION 'Entrega inexistente'; END IF; IF note_id IS NOT NULL AND note_id<>delivery_note THEN RAISE EXCEPTION 'Entrega não pertence à nota selecionada'; END IF; note_id:=delivery_note; END IF; IF note_id IS NOT NULL THEN SELECT carga_id INTO nload FROM notas_fiscais WHERE id=note_id; IF NOT FOUND THEN RAISE EXCEPTION 'Nota inexistente'; END IF; IF load_id IS NOT NULL AND load_id IS DISTINCT FROM nload THEN RAISE EXCEPTION 'Nota não pertence à carga selecionada'; END IF; load_id:=nload; END IF; IF load_id IS NOT NULL THEN IF p.carga_id IS NOT NULL AND p.carga_id<>load_id THEN RAISE EXCEPTION 'Preserve a carga original do envio'; END IF; IF NOT EXISTS(SELECT 1 FROM cargas WHERE id=load_id AND motorista_id=p.motorista_id) THEN RAISE EXCEPTION 'Carga não pertence ao motorista do documento'; END IF; END IF; UPDATE comprovantes SET tipo_documento=_tipo,triagem=_situacao,observacoes_documento=_obs,carga_id=coalesce(carga_id,load_id) WHERE id=_id; IF note_id IS NOT NULL OR load_id IS NOT NULL OR _entrega IS NOT NULL THEN INSERT INTO documento_vinculos(comprovante_id,nota_id,carga_id,entrega_id) SELECT _id,note_id,load_id,_entrega WHERE NOT EXISTS(SELECT 1 FROM documento_vinculos WHERE comprovante_id=_id AND nota_id IS NOT DISTINCT FROM note_id AND carga_id IS NOT DISTINCT FROM load_id AND entrega_id IS NOT DISTINCT FROM _entrega); END IF; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('comprovante',_id,'documento_triado',_tipo||' / '||_situacao||' / '||_obs,auth.uid()); END $$;